//! OS keychain access for chat API keys (macOS Keychain, Windows Credential
//! Manager, Linux kernel keyutils). Secrets are addressed by a short
//! reference such as `provider:<id>` and never touch SQLite or localStorage.

const SERVICE: &str = "com.mynx.chat";

/// Secret references are generated by the app; reject anything unexpected.
pub fn valid_secret_name(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 128
        && name.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, ':' | '_' | '-' | '.'))
}

fn entry(name: &str) -> Result<keyring::Entry, String> {
    if !valid_secret_name(name) {
        return Err(format!("invalid secret name {name:?}"));
    }
    keyring::Entry::new(SERVICE, name).map_err(|e| e.to_string())
}

pub fn set_secret(name: &str, value: &str) -> Result<(), String> {
    entry(name)?.set_password(value).map_err(|e| e.to_string())
}

pub fn get_secret(name: &str) -> Result<Option<String>, String> {
    match entry(name)?.get_password() {
        Ok(value) => Ok(Some(value)),
        Err(keyring::Error::NoEntry) => Ok(None),
        Err(e) => Err(e.to_string()),
    }
}

/// Returns whether a secret existed.
pub fn delete_secret(name: &str) -> Result<bool, String> {
    match entry(name)?.delete_credential() {
        Ok(()) => Ok(true),
        Err(keyring::Error::NoEntry) => Ok(false),
        Err(e) => Err(e.to_string()),
    }
}

#[cfg(test)]
mod tests {
    use super::valid_secret_name;

    #[test]
    fn validates_secret_names() {
        assert!(valid_secret_name("provider:p1"));
        assert!(valid_secret_name("websearch"));
        assert!(!valid_secret_name(""));
        assert!(!valid_secret_name("../etc"));
        assert!(!valid_secret_name("a b"));
        assert!(!valid_secret_name(&"x".repeat(129)));
    }
}
